```c
void producer() {
    while (1) {
        item x = produce();
        wait(empty);
        wait(mutex);
        insert(x);
        signal(mutex);
        signal(full);
    }
}

void consumer() {
    while (1) {
        wait(mutex);
        wait(full);
        item y = remove_item();
